import { encodeCsvField } from './csv-field.mjs';
export function parseCsv(text) {
  if (text === '') return [];
  return text.split('\n').map(line => line.split(','));
}
export function serializeCsv(rows) {
  return rows.map(row => row.map(encodeCsvField).join(',')).join('\r\n');
}

